<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Shopping Online</title>
  <link rel="stylesheet" href="/css/style.css">
</head>
<body>
  <%- include('partials/header') %>

  <main class="container">
    <section class="hero">
      <div>
        <h1>Loja virtual de departamentos</h1>
        <p>Produtos para casa, eletrônicos, moda, informática, livros e muito mais.</p>
      </div>
    </section>

    <section class="card">
      <form class="filters" action="/" method="get">
        <input type="text" name="search" placeholder="Buscar produtos..." value="<%= search %>">

        <select name="category">
          <option value="">Todas as categorias</option>
          <% categories.forEach(cat => { %>
            <option value="<%= cat.category %>" <%= category === cat.category ? 'selected' : '' %>>
              <%= cat.category %>
            </option>
          <% }) %>
        </select>

        <button type="submit">Buscar</button>
      </form>
    </section>

    <section class="grid">
      <% if (products.length === 0) { %>
        <div class="card">
          <p>Nenhum produto encontrado.</p>
        </div>
      <% } %>

      <% products.forEach(product => { %>
        <article class="product">
          <img src="<%= product.image_url || '/img/no-image.svg' %>" alt="<%= product.name %>">
          <div class="product-body">
            <span class="tag"><%= product.category || 'Geral' %></span>
            <h2><%= product.name %></h2>
            <p><%= product.description %></p>
            <strong class="price"><%= money(product.price) %></strong>
            <small>Estoque: <%= product.stock %></small>

            <% if (product.stock > 0) { %>
              <form action="/cart/add/<%= product.id %>" method="post" class="buy-form">
                <input type="number" name="quantity" min="1" max="<%= product.stock %>" value="1">
                <button type="submit">Adicionar ao carrinho</button>
              </form>
            <% } else { %>
              <button disabled>Esgotado</button>
            <% } %>
          </div>
        </article>
      <% }) %>
    </section>
  </main>

  <%- include('partials/footer') %>
</body>
</html>

