* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: Arial, Helvetica, sans-serif;
  background: #f4f6f8;
  color: #1f2937;
}

a {
  color: #2563eb;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

.topbar {
  background: #111827;
  color: white;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  position: sticky;
  top: 0;
  z-index: 10;
}

.brand {
  color: white;
  font-weight: bold;
  font-size: 22px;
}

.brand:hover {
  text-decoration: none;
}

.nav {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}

.nav a,
.nav .hello {
  color: white;
  font-size: 14px;
}

.inline {
  display: inline;
}

.link-button {
  background: transparent;
  border: 0;
  color: white;
  cursor: pointer;
  font-size: 14px;
  padding: 0;
}

.container {
  width: min(1180px, calc(100% - 32px));
  margin: 24px auto;
}

.container.small {
  width: min(480px, calc(100% - 32px));
}

.hero {
  background: linear-gradient(135deg, #2563eb, #7c3aed);
  color: white;
  border-radius: 18px;
  padding: 36px;
  margin-bottom: 20px;
}

.hero h1 {
  margin: 0 0 8px;
  font-size: clamp(28px, 5vw, 46px);
}

.hero p {
  margin: 0;
  font-size: 18px;
}

.card {
  background: white;
  border-radius: 14px;
  padding: 22px;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.08);
  margin-bottom: 20px;
}

.filters {
  display: grid;
  grid-template-columns: 1fr 220px auto;
  gap: 12px;
}

input,
select,
textarea,
button {
  font: inherit;
}

input,
select,
textarea {
  width: 100%;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  padding: 11px 12px;
  background: white;
}

button,
.button {
  display: inline-block;
  border: 0;
  border-radius: 10px;
  padding: 11px 14px;
  background: #2563eb;
  color: white;
  cursor: pointer;
  font-weight: bold;
}

button:hover,
.button:hover {
  background: #1d4ed8;
  text-decoration: none;
}

button:disabled {
  background: #94a3b8;
  cursor: not-allowed;
}

button.danger {
  background: #dc2626;
}

button.danger:hover {
  background: #b91c1c;
}

.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
}

.product {
  background: white;
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.08);
  display: flex;
  flex-direction: column;
}

.product img {
  width: 100%;
  height: 220px;
  object-fit: cover;
  background: #e5e7eb;
}

.product-body {
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 9px;
  flex: 1;
}

.product h2 {
  margin: 0;
  font-size: 20px;
}

.product p {
  margin: 0;
  color: #4b5563;
  flex: 1;
}

.tag {
  background: #e0ecff;
  color: #1d4ed8;
  padding: 5px 9px;
  border-radius: 999px;
  font-size: 12px;
  width: fit-content;
  font-weight: bold;
}

.price {
  font-size: 22px;
  color: #111827;
}

.buy-form {
  display: grid;
  grid-template-columns: 80px 1fr;
  gap: 10px;
  margin-top: 8px;
}

.form {
  display: grid;
  gap: 14px;
}

.form label {
  display: grid;
  gap: 6px;
  font-weight: bold;
}

.form .check {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: normal;
}

.form .check input {
  width: auto;
}

.alert {
  background: #fee2e2;
  color: #991b1b;
  border: 1px solid #fecaca;
  padding: 12px;
  border-radius: 10px;
  margin-bottom: 14px;
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  min-width: 720px;
}

th,
td {
  border-bottom: 1px solid #e5e7eb;
  padding: 12px;
  text-align: left;
  vertical-align: middle;
}

th {
  color: #374151;
  background: #f8fafc;
}

.cart-product {
  display: flex;
  align-items: center;
  gap: 10px;
}

.cart-product img {
  width: 58px;
  height: 58px;
  object-fit: cover;
  border-radius: 10px;
}

.qty-form {
  display: flex;
  gap: 8px;
  align-items: center;
}

.qty-form input {
  width: 90px;
